def cfg(s):
 return {'engine':s.render.engine,'samples':s.cycles.samples,'adaptive_sampling':s.cycles.use_adaptive_sampling,'cycles_denoising':s.cycles.use_denoising,'view_layer_denoising':[l.cycles.use_denoising for l in s.view_layers],'threads_mode':s.render.threads_mode,'threads':s.render.threads,'compositor_nodes':s.use_nodes,'compositing':s.render.use_compositing}
def render_contract(s):
 s.render.engine='CYCLES';s.cycles.samples=128;s.cycles.use_adaptive_sampling=False;s.cycles.use_denoising=False
 s.render.threads_mode='FIXED';s.render.threads=4;s.use_nodes=False;s.render.use_compositing=False
 for l in s.view_layers:l.cycles.use_denoising=False
 return cfg(s)
def pbr(m):
 assert m and m.use_nodes
 p=m.node_tree.nodes.get('Principled BSDF');assert p is not None
 assert not any(i.is_linked for i in p.inputs),'Linked Principled inputs forbidden for full solid-PBR matching'
 assert not any(n.type.startswith('TEX_') for n in m.node_tree.nodes),'Solid-only material required'
 names=['Base Color','Metallic','Roughness','Alpha','IOR','Specular IOR Level','Transmission Weight','Coat Weight','Coat Roughness','Sheen Weight','Emission Color','Emission Strength']
 values=[]
 for name in names:
  v=p.inputs[name].default_value;values.append((name,tuple(round(float(x),6) for x in v) if hasattr(v,'__len__') else round(float(v),6)))
 values.append(('double_sided',not m.use_backface_culling));return tuple(values)
def vworld(o):return [o.matrix_world@v.co for v in o.data.vertices]
def bounds(obs):
 vv=[v for o in obs for v in vworld(o)];lo=[min(v[k] for v in vv) for k in range(3)];hi=[max(v[k] for v in vv) for k in range(3)]
 return {'min':lo,'max':hi,'dimensions':[hi[k]-lo[k] for k in range(3)]}
def rows(obs,transform=None):
 result=[]
 for o in obs:
  o.data.calc_loop_triangles();vv=vworld(o)
  if transform is not None:vv=[transform@v for v in vv]
  for t in o.data.loop_triangles:result.append((tuple(vv[i].copy() for i in t.vertices),pbr(o.data.materials[t.material_index])))
 return result
def canonical(rr):
 return sorted((min(tuple(tuple(round(float(c),6) for c in xyz[(i+j)%3]) for i in range(3)) for j in range(3)),mat) for xyz,mat in rr)
def digest(rr):return hashlib.sha256(json.dumps(canonical(rr),separators=(',',':')).encode()).hexdigest()
def match(actual,expected,label):
 assert len(actual)==len(expected),(label,'triangle count',len(actual),len(expected))
 kd=KDTree(len(expected))
 for i,(p,m) in enumerate(expected):kd.insert(sum(p,Vector())/3,i)
 kd.balance();used=set();maximum=0.
 for p,m in actual:
  candidates=[]
  for c,i,d in kd.find_range(sum(p,Vector())/3,TOL*2):
   if i in used or expected[i][1]!=m:continue
   q=expected[i][0];e=min(max(abs(float(p[(j+s)%3][k]-q[j][k])) for j in range(3) for k in range(3)) for s in range(3))
   if e<=TOL:candidates.append((e,i))
  assert candidates,(label,'oriented triangle or full PBR mismatch',list(p[0]),m)
  e,i=min(candidates);used.add(i);maximum=max(maximum,e)
 assert len(used)==len(expected)
 return {'case':label,'oriented_triangles_matched_once':len(actual),'max_coordinate_error_m':maximum,'coordinate_tolerance_m':TOL,'full_solid_pbr_match':True,'reverse_winding_allowed':False}
def clean_scene(s):
 for o in list(s.objects):bpy.data.objects.remove(o,do_unlink=True)
 bpy.context.window.scene=scene;bpy.data.scenes.remove(s)
 for d in list(bpy.data.meshes):
  if d.users==0:bpy.data.meshes.remove(d)
 for d in list(bpy.data.materials):
  if d.users==0:bpy.data.materials.remove(d)
