 for k in range(3):
  for value,sign in [(box[0][k],1),(box[1][k],-1)]:
   old=poly;poly=[]
   if not old:return []
   p=old[-1];dp=sign*(p[k]-value)
   for q in old:
    dq=sign*(q[k]-value)
